SELECT ROUND(100.0 * AVG(CASE WHEN satisfaction IN (4, 5) THEN 1 ELSE 0 END), 2) AS percentage
FROM tickets
WHERE satisfaction IS NOT NULL;

SELECT ROUND(AVG(merchandise_minor) / CAST(
    (SELECT value FROM shop_meta WHERE key = 'minor_units_per_dollar') AS REAL
), 2) AS average_merchandise_value_dollars
FROM (
    SELECT COALESCE(SUM(oi.quantity * oi.unit_price_minor), 0) AS merchandise_minor
    FROM orders AS o
    LEFT JOIN order_items AS oi ON oi.order_id = o.id
    WHERE o.status = 'canceled'
    GROUP BY o.id
) AS canceled_orders;
